import paradox.music.nativeui.*;import android.app.*;import java.nio.file.*;import java.io.*;import java.lang.reflect.*;
public class TraceLastHarness{public static void main(String[]a)throws Exception{Application app=new Application();app.getFilesDir().mkdirs();NativeMusicDiagnostics.install(app);Thread.sleep(100);NativeMusicDiagnostics.begin();NativeMusicDiagnostics.phase("fixture component construction");Thread.sleep(2400);String summary=NativeMusicStartupTrace.readSummary();if(!summary.startsWith("LAST SAMPLE +")||!summary.contains("fixture component construction")||!summary.contains("NOT CONFIRMED"))throw new AssertionError(summary);String one=summary.split("\\n")[0];Thread.sleep(1000);String two=NativeMusicStartupTrace.readSummary().split("\\n")[0];if(one.equals(two))throw new AssertionError("last sample not refreshing");File state=new File(app.getFilesDir(),"ultra-music-startup-state.txt");String before=new String(Files.readAllBytes(state.toPath()));Method ack=NativeMusicDiagnostics.class.getDeclaredMethod("acknowledge");ack.setAccessible(true);ack.invoke(null);Thread.sleep(200);if(!state.exists())throw new AssertionError("ack erased active attempt");NativeMusicDiagnostics.libraryReady();Thread.sleep(300);if(state.exists())throw new AssertionError("success left interrupted marker");String last=new String(Files.readAllBytes(new File(app.getFilesDir(),"ultra-music-last-attempt.txt").toPath()));if(!last.contains("Library-ready: selected Library tab drawn")||last.contains("Start-to-Library-ready: NOT CONFIRMED"))throw new AssertionError(last);System.out.println("PASS latest sample refresh and first-position summary, active-attempt acknowledgement safety, persistent Library-ready elapsed time and completed-marker cleanup");System.exit(0);}}
